using ControlGastos.Core.Entities; using ControlGastos.Core.Interfaces; using ControlGastos.Infrastructure.Data; using Microsoft.EntityFrameworkCore;
namespace ControlGastos.Infrastructure.Repositories;
public sealed class VinculacionTelegramRepository(ControlGastosDbContext db) : IVinculacionTelegramRepository { public async Task CrearAsync(VinculacionTelegram x,CancellationToken ct){db.VinculacionesTelegram.Add(x);await db.SaveChangesAsync(ct);} public Task<VinculacionTelegram?> ObtenerValidaAsync(string token,CancellationToken ct)=>db.VinculacionesTelegram.SingleOrDefaultAsync(x=>x.CodigoToken==token&&!x.EstaUsado&&x.FechaExpiracion>DateTimeOffset.UtcNow,ct); public async Task MarcarUsadaAsync(long id,CancellationToken ct){var x=await db.VinculacionesTelegram.SingleOrDefaultAsync(x=>x.IdVinculacion==id,ct);if(x is null)return;x.EstaUsado=true;await db.SaveChangesAsync(ct);}}
